class Solution:
    def minimumFinishTime(self, tires: List[List[int]], changeTime: int, numLaps: int) -> int:
        INF = float('inf')
        minF = min(f for f, _ in tires)
        limit = minF + changeTime
        best = [INF] * (numLaps + 1)
        maxlen = 0
        for f, r in tires:
            lap = f
            total = 0
            x = 0
            while x < numLaps and lap <= limit:
                total += lap
                x += 1
                if total < best[x]:
                    best[x] = total
                lap *= r
            maxlen = max(maxlen, x)
        dp = [-changeTime] + [INF] * numLaps
        for j in range(1, numLaps + 1):
            for x in range(1, min(j, maxlen) + 1):
                if best[x] == INF:
                    break
                v = dp[j - x] + changeTime + best[x]
                if v < dp[j]:
                    dp[j] = v
        return dp[numLaps]

