import sys
from functools import lru_cache


class Solution:
    def minimumFinishTime(self, tires: List[List[int]], changeTime: int, numLaps: int) -> int:
        sys.setrecursionlimit(5000)
        INF = float('inf')
        minF = min(f for f, _ in tires)
        limit = minF + changeTime
        best = [INF] * (numLaps + 1)
        for f, r in tires:
            lap = f
            total = 0
            x = 0
            while x < numLaps and lap <= limit:
                total += lap
                x += 1
                if total < best[x]:
                    best[x] = total
                lap *= r

        @lru_cache(None)
        def solve(j):
            if j == 0:
                return 0
            res = INF
            for x in range(1, j + 1):
                if best[x] == INF:
                    break
                res = min(res, best[x] + (changeTime + solve(j - x) if x < j else 0))
            return res

        return solve(numLaps)

