class Solution {
public:
    int minimumFinishTime(vector<vector<int>>& tires, int changeTime, int numLaps) {
        const long long INF = LLONG_MAX / 4;
        int minF = INT_MAX;
        for (auto& t : tires) minF = min(minF, t[0]);
        long long limit = (long long)minF + changeTime;
        vector<long long> best(numLaps + 1, INF);
        for (auto& t : tires) {
            long long lap = t[0], total = 0;
            int x = 0;
            while (x < numLaps && lap <= limit) {
                total += lap;
                x++;
                best[x] = min(best[x], total);
                lap *= t[1];
            }
        }
        vector<long long> memo(numLaps + 1, -1);
        function<long long(int)> solve = [&](int j) -> long long {
            if (j == 0) return 0;
            long long& m = memo[j];
            if (m != -1) return m;
            long long res = INF;
            for (int x = 1; x <= j; x++) {
                if (best[x] == INF) break;
                long long cand = best[x] + (x < j ? changeTime + solve(j - x) : 0LL);
                res = min(res, cand);
            }
            return m = res;
        };
        return (int)solve(numLaps);
    }
};

