class Solution {
    private long[] memo, best;

    public int minimumFinishTime(int[][] tires, int changeTime, int numLaps) {
        final long INF = Long.MAX_VALUE / 4;
        int minF = Integer.MAX_VALUE;
        for (int[] t : tires) minF = Math.min(minF, t[0]);
        long limit = (long) minF + changeTime;
        best = new long[numLaps + 1];
        Arrays.fill(best, INF);
        for (int[] t : tires) {
            long lap = t[0], total = 0;
            int x = 0;
            while (x < numLaps && lap <= limit) {
                total += lap;
                x++;
                best[x] = Math.min(best[x], total);
                lap *= t[1];
            }
        }
        memo = new long[numLaps + 1];
        Arrays.fill(memo, -1);
        return (int) solve(numLaps, changeTime);
    }

    private long solve(int j, int changeTime) {
        if (j == 0) return 0;
        if (memo[j] != -1) return memo[j];
        long res = Long.MAX_VALUE / 4;
        for (int x = 1; x <= j; x++) {
            if (best[x] == Long.MAX_VALUE / 4) break;
            res = Math.min(res, best[x] + (x < j ? changeTime + solve(j - x, changeTime) : 0));
        }
        return memo[j] = res;
    }
}

